"""Regenerate the CPython 3.12 code-equality pyc corpus.

Usage:
  python3.12 -I tests/fixtures/pythonPycCodeEquality.py > tests/fixtures/pythonPycCodeEquality.ts
  npx oxfmt tests/fixtures/pythonPycCodeEquality.ts

CPython produces every code object and the marshal stream. Each case marshals
a module whose co_consts holds a two-member tuple of code objects, then reframes
that tuple as a frozenset. Marshal format 2 writes no TYPE_REF back-references,
so the tuple's bytes are context-free and the reframed stream stays valid.
CPython's own marshal.loads is the oracle for each frozenset's cardinality and
for which member it keeps. The fixtures are parsed only, never executed.
"""

from __future__ import annotations

import importlib.util
import marshal
import sys
import types

if sys.version_info[:2] != (3, 12):
    raise SystemExit("Run with CPython 3.12; the corpus pins the 3.12 layout.")

SOURCE = "def f(a):\n    try:\n        return a + 1\n    except E:\n        return 0\n"
# Same statements, different columns: only co_linetable changes.
COLUMN_SHIFTED = SOURCE.replace("return a + 1", "return  a + 1")
TYPE_TUPLE = 0x28
TYPE_FROZENSET = 0x3E


def function_code(source: str) -> types.CodeType:
    module = compile(source, "m.py", "exec")
    return next(c for c in module.co_consts if isinstance(c, types.CodeType))


def replace_const(code: types.CodeType, old: object, new: object) -> types.CodeType:
    consts = tuple(
        new if type(c) is type(old) and c == old else c for c in code.co_consts
    )
    if [type(c) for c in consts] == [type(c) for c in code.co_consts]:
        raise SystemExit(f"Constant {old!r} not found")
    return code.replace(co_consts=consts)


base = function_code(SOURCE)
zero = base.replace(co_consts=(None, 1, 0.0))

# (name, what differs, first member, second member)
CASES = [
    ("identical", "nothing", base, base.replace()),
    ("qualname", "co_qualname", base, base.replace(co_qualname="g.<locals>.f")),
    ("stacksize", "co_stacksize", base, base.replace(co_stacksize=base.co_stacksize + 5)),
    ("filename", "co_filename", base, base.replace(co_filename="other.py")),
    ("name", "co_name", base, base.replace(co_name="h")),
    ("firstlineno", "co_firstlineno", base, base.replace(co_firstlineno=base.co_firstlineno + 1)),
    ("linetable", "co_linetable", base, base.replace(co_linetable=function_code(COLUMN_SHIFTED).co_linetable)),
    ("exceptiontable", "co_exceptiontable", base, base.replace(co_exceptiontable=b"")),
    ("int_vs_float_const", "co_consts 1 versus 1.0", base, replace_const(base, 1, 1.0)),
    ("signed_zero_const", "co_consts 0.0 versus -0.0", zero, zero.replace(co_consts=(None, 1, -0.0))),
]


def pyc(first: types.CodeType, second: types.CodeType) -> tuple[bytes, frozenset]:
    module = compile("pass", "m.py", "exec")
    module = module.replace(co_consts=module.co_consts + ((first, second),))
    stream = marshal.dumps(module, 2)
    members = marshal.dumps((first, second), 2)
    if members[0] != TYPE_TUPLE or stream.count(members) != 1:
        raise SystemExit("Member tuple is not uniquely locatable")
    stream = stream.replace(members, bytes([TYPE_FROZENSET]) + members[1:])
    loaded = marshal.loads(stream).co_consts[-1]
    if type(loaded) is not frozenset:
        raise SystemExit("Reframed constant did not load as a frozenset")
    header = importlib.util.MAGIC_NUMBER + bytes(12)
    return header + stream, loaded


def ts(value: object) -> str:
    if isinstance(value, str):
        return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'
    return str(value)


rows = []
for name, differs, first, second in CASES:
    data, loaded = pyc(first, second)
    kept = next(iter(loaded)) if len(loaded) == 1 else None
    kept_fields = (
        "null"
        if kept is None
        else "{ qualname: %s, filename: %s, stacksize: %d }"
        % (ts(kept.co_qualname), ts(kept.co_filename), kept.co_stacksize)
    )
    rows.append(
        "  {\n"
        f"    name: {ts(name)},\n"
        f"    differs: {ts(differs)},\n"
        f"    cpythonEqual: {'true' if first == second else 'false'},\n"
        f"    frozensetLength: {len(loaded)},\n"
        f"    kept: {kept_fields},\n"
        f"    hex: {ts(data.hex())},\n"
        "  },"
    )

print(
    f"""// Generated by tests/fixtures/pythonPycCodeEquality.py with CPython {sys.version.split()[0]}.
// Do not edit by hand. Expected values are CPython's marshal.loads results.

export type PythonPycEqualityCase = {{
  readonly name: string;
  readonly differs: string;
  /** CPython `first == second` for the two marshalled code objects. */
  readonly cpythonEqual: boolean;
  /** `len()` of the frozenset CPython loads from this pyc. */
  readonly frozensetLength: number;
  /** The member CPython keeps when the two are equal. */
  readonly kept: {{
    readonly qualname: string;
    readonly filename: string;
    readonly stacksize: number;
  }} | null;
  readonly hex: string;
}};

export const PYTHON_PYC_EQUALITY_PRODUCER = "CPython {sys.version.split()[0]}";
export const PYTHON_PYC_EQUALITY_MAGIC = {int.from_bytes(importlib.util.MAGIC_NUMBER[:2], "little")};

export const pythonPycEqualityCases: readonly PythonPycEqualityCase[] = [
{chr(10).join(rows)}
];"""
)
